{
  "requirements": [
    {
      "id": "REQ-01",
      "title": "Storage within the EEA",
      "description": "The supplier must store Sfera personal data, including replicas, backups, and diagnostic logs, exclusively within the territory of the European Economic Area (EEA).",
      "applicability_text": "Applies to all suppliers handling Sfera personal data.",
      "severity": "High",
      "source": {
        "chunk_id": "658de008-0722-57e4-8f15-2178682f6700",
        "document_id": "2f50a490-2d42-5c0c-ae80-6d9f9ea11aac",
        "location": {
          "line_start": 9,
          "line_end": 11
        },
        "quote": "Dane osobowe Sfera, w tym repliki, kopie zapasowe i dzienniki diagnostyczne, muszą być przechowywane wyłącznie na terenie Europejskiego Obszaru Gospodarczego (EOG)."
      }
    },
    {
      "id": "REQ-02",
      "title": "Remote Access Outside the EEA",
      "description": "Remote access to Sfera personal data from outside the EEA requires prior written consent from Sfera for the specified country and purpose. Storing data within the EEA does not constitute such consent.",
      "applicability_text": "Applies to all suppliers requesting or performing remote access to Sfera personal data.",
      "severity": "High",
      "source": {
        "chunk_id": "658de008-0722-57e4-8f15-2178682f6700",
        "document_id": "2f50a490-2d42-5c0c-ae80-6d9f9ea11aac",
        "location": {
          "line_start": 13,
          "line_end": 15
        },
        "quote": "Dostęp zdalny do danych osobowych Sfera spoza EOG wymaga uprzedniej, pisemnej zgody Sfera dla wskazanego kraju i celu. Samo przechowywanie danych w EOG nie stanowi takiej zgody."
      }
    },
    {
      "id": "REQ-03",
      "title": "Notification of Location Change",
      "description": "The supplier must notify Sfera of any planned change in the country of data storage at least 21 calendar days prior to the change.",
      "applicability_text": "Applies to all suppliers intending to change the storage location of Sfera data.",
      "severity": "Medium",
      "source": {
        "chunk_id": "658de008-0722-57e4-8f15-2178682f6700",
        "document_id": "2f50a490-2d42-5c0c-ae80-6d9f9ea11aac",
        "location": {
          "line_start": 17,
          "line_end": 17
        },
        "quote": "Dostawca musi powiadomić Sfera o planowanej zmianie kraju przechowywania danych co najmniej 21 dni kalendarzowych przed zmianą."
      }
    }
  ]
}

